// Internal relay: the Worker hands operator notifications to Pages, which
// already holds RESEND_API_KEY. Authenticated with INTERNAL_NOTIFY_SECRET
// (generated by Claude, installed on both sides, never typed by a person).
//   POST /api/notify  {title, lines[], link}   header x-internal-secret
import { json, str } from "../_shared/common.js";
import { notifyOperator } from "../_shared/notify-operator.js";

function sameSecret(a, b) {
  if (!a || !b || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i += 1) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

export async function onRequestPost({ request, env }) {
  if (!sameSecret(request.headers.get("x-internal-secret") || "", env.INTERNAL_NOTIFY_SECRET || "")) {
    return json({ ok: false, error: "unauthorized" }, 401);
  }
  let body = {};
  try { body = await request.json(); } catch { return json({ ok: false, error: "invalid JSON" }, 400); }
  const title = str(body.title).slice(0, 200);
  if (!title) return json({ ok: false, error: "title required" }, 422);
  const lines = Array.isArray(body.lines) ? body.lines.map((l) => str(l).slice(0, 500)).filter(Boolean).slice(0, 20) : [];
  const result = await notifyOperator(env, { title, lines, link: str(body.link).slice(0, 300) });
  return json({ ok: result.ok, delivered: result.delivered });
}
